export const POWER_CLASSES = ['Aerial', 'Energy', 'Psionic', 'Tech', 'Mutant', 'Cosmic', 'Enhanced'] as const;
export type PowerClass = (typeof POWER_CLASSES)[number];

export const HERO_STATUSES = ['Active', 'Injured', 'Reserve', 'MIA'] as const;
export type HeroStatus = (typeof HERO_STATUSES)[number];

export const CLEARANCE_TIERS = [1, 2, 3, 4, 5] as const;
export type ClearanceTier = (typeof CLEARANCE_TIERS)[number];

export function clearanceLabel(tier: ClearanceTier): string {
  return `Tier ${tier}`;
}

export interface Hero {
  /** Roster id, e.g. "HRO-0007". Never changes after recruitment. */
  readonly id: string;
  readonly name: string;
  readonly alias: string;
  readonly powerClass: PowerClass;
  /** Power index, 0 to 100. */
  readonly powerIndex: number;
  readonly status: HeroStatus;
  readonly clearanceTier: ClearanceTier;
  readonly missionCount: number;
  /** Mission success rate as a percentage, 0 to 100. */
  readonly successRate: number;
  /** Free-text dossier notes. */
  readonly notes: string;
}
import { Service, signal } from '@angular/core';
import type { Hero } from './hero.model';
import { EXAMPLE_HEROES } from './hero.seed';

/**
 * In-memory roster. EXAMPLE DATA ONLY: there is no backend, so every change lives in
 * signal state and is lost on reload. Routed screens read it through their ViewModels.
 */
@Service()
export class HeroService {
  private readonly state = signal<readonly Hero[]>(EXAMPLE_HEROES);

  readonly heroes = this.state.asReadonly();

  findById(id: string): Hero | undefined {
    return this.state().find((hero) => hero.id === id);
  }

  /** Applies a partial update to one hero. The id is fixed and cannot be patched. */
  update(id: string, patch: Partial<Omit<Hero, 'id'>>): Hero | undefined {
    const current = this.findById(id);
    if (!current) {
      return undefined;
    }
    const next: Hero = { ...current, ...patch };
    this.state.update((heroes) => heroes.map((hero) => (hero.id === id ? next : hero)));
    return next;
  }
}
