import { Component, computed, input } from '@angular/core';
import { RouterLink } from '@angular/router';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmBadgeImports } from '@spartan-ng/helm/badge';
import { HlmCardImports } from '@spartan-ng/helm/card';
import { HlmTypographyImports } from '@spartan-ng/helm/typography';
import type { Hero, HeroStatus } from '../domain/hero.model';
import { PowerMeter } from './power-meter';

type StatusBadge = 'default' | 'secondary' | 'outline' | 'destructive';

// Attention-worthy statuses get the louder badges.
const STATUS_BADGE: Record<HeroStatus, StatusBadge> = {
  Active: 'secondary',
  Reserve: 'outline',
  Injured: 'default',
  MIA: 'destructive',
};

// "Dr. Ion" -> "DI", "The Tinkerer" -> "TT".
function initialsOf(name: string): string {
  return name
    .replace(/[^\p{L}\s]/gu, '')
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((word) => word.charAt(0).toUpperCase())
    .join('');
}

// One hero as a card: portrait, identity, class and status, power, and record. Inputs only.
@Component({
  selector: 'app-hero-card',
  imports: [RouterLink, HlmAvatarImports, HlmBadgeImports, HlmCardImports, HlmTypographyImports, PowerMeter],
  templateUrl: './hero-card.html',
  styleUrl: './hero-card.css',
})
export class HeroCard {
  readonly hero = input.required<Hero>();

  protected readonly initials = computed(() => initialsOf(this.hero().name));
  protected readonly statusBadge = computed(() => STATUS_BADGE[this.hero().status]);
}

